import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2020-04-09 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-04-09 -- Ceph Performance Meeting","date":"2020-04-09T00:00:00.000Z","updated":"2020-04-14T00:00:00.000Z","tags":["分布式存储","Ceph","性能优化","PR审核","CI/CD"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-04-09_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-04-09_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-04-09_-_-_Ceph_Performance_Meeting.md"};function o(n,e,s,h,u,_){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：2020年4月9日</li><li>时间：上午</li></ul><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>主持人：未明确</li><li>参会人员：团队研发人员</li></ul><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><ol><li><p><strong>优化和更新</strong></p><ul><li><strong>NVMe设备优化</strong>：讨论了NVMe设备优化的请求，但优先级不高，因为审核人员目前在加拿大。</li><li><strong>OSD线程优化</strong>：ma Jinping提交了更改OSD线程数的请求，讨论了理论测试和实际性能表现，建议进一步审查。</li><li><strong>缓冲列表使用迭代器</strong>：讨论了使用迭代器进行比较操作的优化，已有人进行审核，整体看起来不错。</li></ul></li><li><p><strong>关闭和合并的PR</strong></p><ul><li>多个PR被关闭，包括移除vector的PR和ZLib压缩配置的PR。</li><li>一些优化和文档更新的PR被合并，例如针对throttle的优化和blue FS缓冲I/O的默认禁用。</li></ul></li><li><p><strong>性能测试和CI讨论</strong></p><ul><li>讨论了性能CI的集成，包括Jenkins和CBT框架的使用，以及如何进行长期运行的测试。</li><li>讨论了如何更好地记录和可视化性能测试结果。</li></ul></li><li><p><strong>硬件推荐更新</strong></p><ul><li>文档更新包括硬件推荐，提供了更新的建议，帮助用户了解不同硬件配置的预期性能。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>继续审查和优化PR，特别是性能相关的。</li><li>推进性能CI的集成和长期测试的实施。</li><li>讨论和实施更好的性能测试结果记录和可视化方法。</li></ul></li></ol><h4 id="行动项" tabindex="-1">行动项 <a class="header-anchor" href="#行动项" aria-label="Permalink to &quot;行动项&quot;">​</a></h4><ul><li>继续审查和优化PR，特别是性能相关的。</li><li>推进性能CI的集成和长期测试的实施。</li><li>讨论和实施更好的性能测试结果记录和可视化方法。</li></ul><h4 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h4><ul><li>时间：下周</li><li>内容：继续讨论性能CI的进展和任何需要解决的问题。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议中提到的具体技术细节和代码变更需要进一步的技术文档和代码审查来确保准确性和实施的有效性。</li></ul><p>本次会议重点讨论了Ceph存储系统的性能优化和PR审核情况，同时探讨了性能测试和CI/CD的集成，以及硬件推荐的更新。会议还确定了后续的行动计划，包括审查和优化PR、推进性能CI的实施和改进性能测试结果的记录和可视化方法。</p>',14)])])}const c=l(r,[["render",o]]);export{p as __pageData,c as default};
